    def handle_upload():
        user = app_data["current_user"]

        path, photo = common.upload_profile_picture(user)

        if not path:
            return

        # Save path
        pfp_path["value"] = path
        #profile_preview_img = {"value": None}

        # Ensure user exists
        if user not in app_data["users"] or app_data["users"][user] is None:
            app_data["users"][user] = {}

        app_data["users"][user]["profile_pic"] = path

        #Update UI
        #profile_preview_img["value"] = photo
        profile_preview.config(image=photo, text="", bg="#F9E699")
        profile_preview.image = photo
        # profile_preview.image = photo
