    #focus functions
    def on_entry_focus_in(event):
        event.widget.config(insertwidth=2)  # normal visible caret
        
        if event.widget is firstname:
            canvas.itemconfig(entry_bg_1, image=entry_image_1Blue)
        elif event.widget is lastname:
            canvas.itemconfig(entry_bg_2, image=entry_image_2Blue)
